/// Metadata about a single validated field, generated by `#[derive(RodValidate)]`.
///
/// This is exposed so that UI/form layers can introspect the validation rules
/// at compile time (see the [`RodMetadata`] trait and the helpers in
/// [`combinators::ValidationMetadata`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RodFieldMeta {
    /// The field name. For enum fields this is qualified as `Variant.field`
    /// (or `Variant.index` for unnamed tuple-style fields).
    pub name: &'static str,
    /// The `#[rod(group = "...")]` tag of the field, if any.
    pub group: Option<&'static str>,
    /// Whether the field participates unconditionally in validation.
    /// Fields with an `Option { ... }` rule are marked as not required,
    /// since a serde-serialized `null` is a valid representation for them.
    pub required: bool,
}

/// Static metadata about the fields of a validated type.
///
/// Implemented automatically by `#[derive(RodValidate)]`.
pub trait RodMetadata {
    /// Metadata for every (non-skipped) validated field, in declaration order.
    const FIELDS: &'static [RodFieldMeta];
}

pub trait RodValidate {
    /// Validate the struct, returning an error if validation fails.
    fn validate(&self) -> Result<(), errors::RodValidateError>;
    /// Validate the struct, returning a list of errors if validation fails.
    fn validate_all(&self) -> Result<(), errors::RodValidateErrorList>;
    /// Validate only the fields tagged with `#[rod(group = "name")]` matching
    /// the given group, plus every field that has no group. Group selection
    /// applies recursively: nested `RodValidate` types (including through the
    /// blanket `Box`/`Rc`/`Arc`/`Vec`/`Option` impls) validate with the same
    /// group, so unrelated groups inside them stay silent.
    ///
    /// Types that don't use groups simply validate everything.
    fn validate_group(&self, _group: &str) -> Result<(), errors::RodValidateErrorList> {
        self.validate_all()
    }
    /// Validate every field, regardless of its group.
    fn validate_all_groups(&self) -> Result<(), errors::RodValidateErrorList> {
        self.validate_all()
    }
}

/// `check_all` runs a custom closure that reports **every** issue it finds,
/// instead of failing fast like a plain
/// `check = |x| bool` closure. Use it when one field can be wrong in several
/// ways and the user should see all of them at once:
///
/// ```rust
/// use rod_validation::prelude::*;
///
/// #[derive(RodValidate)]
/// struct Password {
///     #[rod(
///         String { length: 8..=30 },
///         check_all = |p: &String| {
///             let mut issues = Vec::new();
///             if !p.chars().any(|c| c.is_ascii_digit()) {
///                 issues.push("needs a digit");
///             }
///             if !p.chars().any(|c| c.is_ascii_uppercase()) {
///                 issues.push("needs an uppercase letter");
///             }
///             issues
///         }
///     )]
///     password: String,
/// }
///
/// let errors = Password { password: "lowercase".to_string() }.validate_all().unwrap_err();
/// assert_eq!(errors.len(), 2); // both issues, from one closure
/// ```
///
/// `check` and `check_all` are mutually exclusive on the same field:
///
/// ```compile_fail
/// use rod_validation::prelude::*;
///
/// #[derive(RodValidate)]
/// struct Both {
///     #[rod(
///         String { length: 3..=30 },
///         check = |s: &String| !s.is_empty(),
///         check_all = |s: &String| vec![]
///     )]
///     name: String,
/// }
/// ```
///
/// The same applies to their async counterparts: `async_check_all = |x|
/// future_of_messages` awaits a future and collects **every** message it
/// yields as one `UserDefined` error (run only by
/// [`AsyncValidator::validate_async`]), and `async_check` + `async_check_all`
/// cannot share a field:
///
/// ```compile_fail
/// use rod_validation::prelude::*;
///
/// #[derive(RodValidate)]
/// struct Mixed {
///     #[rod(
///         String { length: 3..=30 },
///         async_check = |s: &String| std::future::ready(true),
///         async_check_all = |s: &String| std::future::ready(vec![])
///     )]
///     name: String,
/// }
/// ```

// Re-exported so that code generated by `#[derive(RodValidate)]` can build
// JSON Schemas without requiring `serde_json` to be a direct dependency of
// the deriving crate.
#[cfg(feature = "serde")]
pub use serde_json as __serde_json;

// ---------------------------------------------------------------------------
// Blanket impls for common std containers
//
// Fields whose type is `Box<T>`, `Rc<T>`, `Arc<T>`, `Vec<T>` or `Option<T>`
// (all with `T: RodValidate`) now delegate automatically, so nested data can
// use the usual Rust idioms — heap indirection, shared ownership, item
// collections and optional values — without a manual `impl`:
//
// - `child: Option<Box<Node>>` makes recursive (tree-shaped) validation work,
//   the Rust equivalent of lazy self-referencing schemas
// - `address: Option<Address>` / `shipping: Vec<Address>` validate their
//   contents; `None`/empty are valid
//
// Cyclical values (e.g. two `Rc`s pointing at each other) will recurse
// until the stack overflows; the same is true of any recursive validator —
// cycle at your own risk.
// ---------------------------------------------------------------------------

macro_rules! impl_rod_validate_for_deref_container {
    ($($container:ident),* $(,)?) => {
        $(
            impl<T: RodValidate> RodValidate for $container<T> {
                fn validate(&self) -> Result<(), errors::RodValidateError> {
                    (**self).validate()
                }
                fn validate_all(&self) -> Result<(), errors::RodValidateErrorList> {
                    (**self).validate_all()
                }
                fn validate_group(
                    &self,
                    group: &str,
                ) -> Result<(), errors::RodValidateErrorList> {
                    (**self).validate_group(group)
                }
                fn validate_all_groups(
                    &self,
                ) -> Result<(), errors::RodValidateErrorList> {
                    (**self).validate_all_groups()
                }
            }
        )*
    };
}

use std::boxed::Box;
use std::rc::Rc;
use std::sync::Arc;

impl_rod_validate_for_deref_container!(Box, Rc, Arc);

/// `Vec<T>` validates every item in order; the first failure is returned by
/// `validate`, `validate_all` collects across all items.
impl<T: RodValidate> RodValidate for Vec<T> {
    fn validate(&self) -> Result<(), errors::RodValidateError> {
        for item in self {
            item.validate()?;
        }
        Ok(())
    }
    fn validate_all(&self) -> Result<(), errors::RodValidateErrorList> {
        let mut errors = errors::RodValidateErrorList::new();
        for item in self {
            if let Err(item_errors) = item.validate_all() {
                for error in item_errors {
                    errors.push(error);
                }
            }
        }
        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }
    fn validate_group(
        &self,
        group: &str,
    ) -> Result<(), errors::RodValidateErrorList> {
        let mut errors = errors::RodValidateErrorList::new();
        for item in self {
            if let Err(item_errors) = item.validate_group(group) {
                for error in item_errors {
                    errors.push(error);
                }
            }
        }
        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }
    fn validate_all_groups(
        &self,
    ) -> Result<(), errors::RodValidateErrorList> {
        self.validate_all()
    }
}

/// `Option<T>` validates the `Some` value; `None` is always valid.
impl<T: RodValidate> RodValidate for Option<T> {
    fn validate(&self) -> Result<(), errors::RodValidateError> {
        match self {
            Some(value) => value.validate(),
            None => Ok(()),
        }
    }
    fn validate_all(&self) -> Result<(), errors::RodValidateErrorList> {
        match self {
            Some(value) => value.validate_all(),
            None => Ok(()),
        }
    }
    fn validate_group(
        &self,
        group: &str,
    ) -> Result<(), errors::RodValidateErrorList> {
        match self {
            Some(value) => value.validate_group(group),
            None => Ok(()),
        }
    }
    fn validate_all_groups(
        &self,
    ) -> Result<(), errors::RodValidateErrorList> {
        match self {
            Some(value) => value.validate_all_groups(),
            None => Ok(()),
        }
    }
}

